import {catalogProfiles} from './expanded-catalog.js';
export function extendDetailCopy(details){
 for(const p of catalogProfiles){
  const school=p.field==='高校入試',admission=school||p.field==='大学入試';
  const shared=(p.family==='toeic'||p.family==='eiken'||p.id.startsWith('fp1-gakka-'))?details[p.family]:null;
  const notes=p.procedureNotes||[];
  details[p.id]={...(shared||{}),theme:admission?'peach':p.field.includes('語学')?'cream':p.field.includes('金融')?'sky':'mint',art:admission?'family':p.availability?'discover':'decided',scope:p.edition,
   intro:shared?.intro||(admission?'出願先や選抜の種類が決まったら、期限と当日の予定を順番に確かめていきましょう。ご本人の受ける日程に合わせて、分かるところから準備を進めてくださいね。':'受ける回や方式が決まったら、申し込みと当日の支度を順に見ていきましょう。ご自身に当てはまる案内か確かめながら、少しずつ準備を進めてくださいね。'),
   focus:[p.edition,'申し込む窓口と、受付の条件','会場・時刻と当日の注意事項'],
   advice:admission?'学校の案内も、一緒に確認を':'受ける回と方式を、最初に確認',adviceBody:admission?'同じ地域や大学でも、選抜の種類や学部によって必要な手続きが違うことがあります。志望する学校の募集要項も手元に置いて、予定を確かめてみてくださいね。':'過去の回や、別の方式の案内と取り違えないように、実施回を確かめておきましょう。迷うところは、公式案内にある問い合わせ先へ確認してみてくださいね。',
   resultLabel:p.family==='toeic'?'認定証の発行':admission?'結果・成績の案内':'結果発表など',sources:[[p.sourceTitle,p.sourceUrl],...(p.extraSources||[]).map(s=>[s.title,s.url])],
   steps:shared?.steps||[['準備を始めるとき','受ける回・区分を確かめる',notes[0]||'年度や方式、地域や選抜の種類を確認しましょう。ご自身に当てはまる受験案内を見ながら進めてくださいね。'],['受付の案内を見たら','申し込みの条件を確認する',notes[1]||'提出する書類や、受付・支払いの条件を確認しておきましょう。郵送とWebなどで期限が違わないかも見ておきましょう。'],['手続きのあと','受付状況と当日の案内を確認する',notes[2]||'申込先から案内される受付状況や、受験票などの準備方法を確認します。不明な点は申込先へ確かめておいてくださいね。'],['前日までに','持ち物と会場への行き方を確認',notes[3]||'会場と集合時刻が分かったら、交通手段や出発する時刻も考えておきましょう。必要な持ち物は受験案内と照らし合わせてそろえます。'],['受験のあと','結果と、その後の予定を確認する',notes[4]||'結果を見る方法と、必要な手続きがあるかを確かめましょう。学校への提出や登録などが必要な方は、その期限も見ておきたいですね。']],
   kit:shared?.kit||[['受験票・申込先からの案内','当日必要な案内を、受験する回の公式資料で確認。'],['指定されている書類・用具','必要な書類や使用できる用具を、主催者の一覧と照合。'],['会場までの道順と時刻','会場と集合時刻が分かったら、移動の予定も確認。']],
   day:shared?.day||['出発前に、会場と必要な持ち物を見直す','案内された集合時刻に間に合うよう会場へ向かう','係員の説明や当日の注意事項に沿って受験する'],after:shared?.after||(admission?'合格発表のあとには、入学の手続きが続くことがあります。提出する書類や納付の期限は、学校の募集要項や合格後の案内でも確かめておきましょう。':'結果の確認方法と、証明書や登録などの手続きが必要かを、主催者の案内で確認しておきましょう。'),
   faq:shared?.faq||[['日程がひとつの日付になっていないときは？','予約制の試験や、地域・学校ごとに異なる日程もあります。「未発表」「時期のみ公表」「予約制」を分けてご案内しています。ご自身の条件に合う公式案内をご覧ください。'],['申し込みや当日のことで、分からない点があるときは？','主催者や出願先の募集要項にある問い合わせ先をご確認ください。学校で取りまとめる場合は、担当の方にも相談してみてくださいね。']]
  };
 }
}
